import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ApiService } from '../../core/services/api.service';

@Component({
  selector: 'app-categories',
  standalone: true,
  imports: [CommonModule, FormsModule],
  template: `
    <div class="page-header"><div class="container"><h2>Quản lý Danh mục</h2></div></div>
    <section class="section">
      <div class="container">
        <div class="grid grid-2">
          <div class="card"><div class="card-body">
            <h3>Điểm đến</h3>
            <div *ngFor="let c of destCategories" class="cat-item">
              <span>{{ c.name }} ({{ c._count?.destinations }})</span>
              <button class="btn btn-sm btn-danger" (click)="delete('destinations', c.id)">Xóa</button>
            </div>
            <div class="add-form"><input type="text" class="form-control" [(ngModel)]="newDestCat" placeholder="Tên danh mục mới"><button class="btn btn-primary btn-sm" (click)="add('destinations')">Thêm</button></div>
          </div></div>
          <div class="card"><div class="card-body">
            <h3>Bài viết</h3>
            <div *ngFor="let c of artCategories" class="cat-item">
              <span>{{ c.name }} ({{ c._count?.articles }})</span>
              <button class="btn btn-sm btn-danger" (click)="delete('articles', c.id)">Xóa</button>
            </div>
            <div class="add-form"><input type="text" class="form-control" [(ngModel)]="newArtCat" placeholder="Tên danh mục mới"><button class="btn btn-primary btn-sm" (click)="add('articles')">Thêm</button></div>
          </div></div>
        </div>
      </div>
    </section>
  `,
  styles: [`.cat-item { display:flex; justify-content:space-between; align-items:center; padding:0.75rem 0; border-bottom:1px solid #f1f5f9; } .add-form { display:flex; gap:0.5rem; margin-top:1rem; input { flex:1; } }`]
})
export class CategoriesComponent implements OnInit {
  destCategories: any[] = [];
  artCategories: any[] = [];
  newDestCat = '';
  newArtCat = '';
  constructor(private api: ApiService) {}
  ngOnInit() {
    this.api.getDestinationCategories().subscribe(d => { this.destCategories = d; });
    this.api.getArticleCategories().subscribe(d => { this.artCategories = d; });
  }
  add(type: string) {
    const name = type === 'destinations' ? this.newDestCat : this.newArtCat;
    if (!name.trim()) return;
    const slug = name.toLowerCase().replace(/ /g, '-').replace(/[^\w-]/g, '');
    const action = type === 'destinations' ? this.api.getDestinationCategories() : this.api.getArticleCategories();
    // Create via raw fetch since no create endpoint exposed
    fetch('http://localhost:3000/api/categories/' + type, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + localStorage.getItem('auth_token') },
      body: JSON.stringify({ name, slug })
    }).then(() => location.reload());
  }
  delete() {}
}
